# Function: gapfill_precipitation

import os
import tempfile

import numpy as np
import pandas as pd


WINDOW_HALF_WIDTH = 15  # days on each side, on the day-of-year circle
N_POSITIONS = 366       # leap-year calendar positions: Jan 1 = 0, Feb 29 = 59, Dec 31 = 365


def _calendar_position(dates: pd.DatetimeIndex) -> np.ndarray:
    """Position of each date on a 366-slot day-of-year circle.

    Uses the leap-year calendar for every year, so Feb 29 sits between Feb 28
    and Mar 1, and a given month/day always maps to the same slot.
    """
    ref = pd.to_datetime(
        {"year": np.full(len(dates), 2000), "month": dates.month, "day": dates.day}
    )
    return (ref.dt.day_of_year.to_numpy() - 1).astype(int)


def gapfill_precipitation(folder: str, input1: str, output1: str) -> None:
    tmpdir = tempfile.mkdtemp(prefix="gapfill_")
    local_in = os.path.join(tmpdir, "ghcn_daily.csv")
    local_out = os.path.join(tmpdir, "precip_gapfilled.csv")

    faasr_get_file(local_file=local_in, remote_folder=folder, remote_file=input1)

    try:
        raw = pd.read_csv(local_in, usecols=["DATE", "PRCP"], dtype=str)
    except ValueError as e:
        faasr_log(f"gapfill_precipitation: input {input1} lacks DATE/PRCP columns: {e}")
        raise

    raw["DATE"] = pd.to_datetime(raw["DATE"].str.strip(), format="%Y-%m-%d", errors="coerce")
    raw = raw.dropna(subset=["DATE"])
    if raw.empty:
        msg = f"gapfill_precipitation: no valid DATE rows in {input1}"
        faasr_log(msg)
        raise ValueError(msg)

    raw["prcp_mm"] = pd.to_numeric(raw["PRCP"].str.strip(), errors="coerce") / 10.0

    # One value per date: if a date is repeated, keep its first observed value.
    raw = raw.sort_values("DATE")
    per_day = raw.groupby("DATE")["prcp_mm"].first()

    if per_day.notna().sum() == 0:
        msg = f"gapfill_precipitation: no observed PRCP values in {input1}"
        faasr_log(msg)
        raise ValueError(msg)

    start, end = per_day.index.min(), per_day.index.max()
    calendar = pd.date_range(start, end, freq="D")
    series = per_day.reindex(calendar)

    present_dates = calendar.isin(per_day.index)
    observed = series.notna().to_numpy()
    n_days = len(calendar)
    n_absent = int((~present_dates).sum())
    n_empty = int((present_dates & ~observed).sum())
    n_filled = n_absent + n_empty

    # Climatology: mean of observed values within +/-15 days on the day-of-year circle.
    pos = _calendar_position(calendar)
    vals = series.to_numpy()
    sums = np.bincount(pos[observed], weights=vals[observed], minlength=N_POSITIONS)
    counts = np.bincount(pos[observed], minlength=N_POSITIONS).astype(float)
    win_sum = np.zeros(N_POSITIONS)
    win_cnt = np.zeros(N_POSITIONS)
    for k in range(-WINDOW_HALF_WIDTH, WINDOW_HALF_WIDTH + 1):
        win_sum += np.roll(sums, k)
        win_cnt += np.roll(counts, k)
    with np.errstate(invalid="ignore", divide="ignore"):
        clim = np.where(win_cnt > 0, win_sum / win_cnt, np.nan)

    filled_vals = vals.copy()
    filled_vals[~observed] = clim[pos[~observed]]
    if np.isnan(filled_vals).any():
        msg = "gapfill_precipitation: some missing days have no observed values within the +/-15-day window"
        faasr_log(msg)
        raise ValueError(msg)

    out = pd.DataFrame(
        {
            "date": calendar.strftime("%Y-%m-%d"),
            "prcp_raw_mm": np.round(vals, 2),
            "prcp_filled_mm": np.round(filled_vals, 2),
            "filled": (~observed).astype(int),
        }
    )
    out.to_csv(local_out, index=False, na_rep="", float_format="%.2f")

    faasr_log(
        f"gapfill_precipitation: period of record {start.date()} to {end.date()}; "
        f"{n_days} calendar days; {n_filled} days filled "
        f"({n_empty} empty-value days, {n_absent} absent dates); "
        f"{100.0 * n_filled / n_days:.2f}% filled"
    )

    faasr_put_file(local_file=local_out, remote_folder=folder, remote_file=output1)
    faasr_log(f"gapfill_precipitation: uploaded {output1}")
